      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2026/5dec532efefbe1690fbc71ccd5a1ed19aeb3.pdf"
      ],
      "testable_prediction": "An MCD-backed robust thresholding framework will maintain lower false-positive rate inflation (FPR < 0.02) compared to standard sample covariance when commissioning data contains up to 25% adversarial contamination.",
      "caveats": "MCD estimation incurs higher computational overhead, which may challenge resource-constrained edge IoT devices."
    },
    {
      "hypothesis": "Integrating nonparametric pseudo-isolation score thresholding into flexible Gaussian Mixture Models (GMMs) or subspace clustering algorithms preserves probabilistic false-alarm rate control while successfully accommodating non-spherical geometries.",
      "rationale": "Iannaccio and Vichi (2026) established a nonparametric pseudo-isolation framework with formal Cantelli-based probability bounds for spherical K-means, but noted limitations when applied to complex non-spherical clusters.",
      "supporting_papers": [
        "/media/soumik/storage/MTech/ATR/agents/dataset/papers/trimmed_k_means/2026/2609.08494v1.pdf"
      ],
      "testable_prediction": "Extending pseudo-isolation scoring to covariance-adaptive GMMs will achieve an F1-score greater than 0.95 in detecting outliers across highly elliptical synthetic benchmark distributions where standard trimmed K-means fails.",
      "caveats": "Estimating full covariance matrices increases parameter complexity and risks overfitting on small sample sizes."
    }
  ]
}

